const SEV_HIGH = 0.355, SEV_ATRISK = 0.645;
const VIC_SPLIT = [['Excess gambling losses (spend beyond recreational levels)',0.369],['Emotional & psychological',0.234],['Relationship breakdown',0.177],['Lost work & productivity',0.106],['Government services',0.092],['Crime',0.021]];

// ---- Formatters ----
const fmtPop = n => Math.round(n).toLocaleString('en-GB');
function round3sf(n){
  if(n===0) return 0;
  const mag = Math.pow(10, Math.floor(Math.log10(Math.abs(n)))-2);
  return Math.round(n/mag)*mag;
}
const fmtPeople = n => '≈ ' + round3sf(n).toLocaleString('en-GB');
function fmtMoney(n){
  if(n>=1e9) return '£'+(n/1e9).toFixed(2)+'bn';
  if(n>=1e6) return '£'+(n/1e6).toFixed(1)+'m';
  if(n>=1e3) return '£'+Math.round(n/1e3).toLocaleString('en-GB')+'k';
  return '£'+Math.round(n).toLocaleString('en-GB');
}
const dot = (s,r) => s.reduce((acc,v,i)=>acc+v*r[i],0);

// ---- Core calculation engine (ported from calc() in original) ----
function calcAdjForLA(la, cat, eps, basisMode){
  // cat: 0=PGSI1-2, 1=PGSI3-7, 2=PGSI8+
  const R = [R12,R37,R8][cat], rm=[RM12,RM37,RM8][cat], rf=[RF12,RF37,RF8][cat];
  const rre = cat===2 ? RRE8 : RRE17;
  const RD = [RD12,RD37,RD8][cat];
  const eth = (la.e && la.e.W!=null) ? (100-la.e.W) : NAT_ETH;
  const dens = la.g.reduce((a,b)=>a+b,0)/expPop(la)*1e5;
  const dR = Math.min(Math.max(dens/GB_DENS,SUPPLY_CAP[0]),SUPPLY_CAP[1]);
  const mA = (dot(la.ab,R)/dot(NAT_AB,R))
    * ((la.m*rm+(100-la.m)*rf)/(NAT_MALE*rm+(100-NAT_MALE)*rf))
    * (((100-eth)+eth*rre)/((100-NAT_ETH)+NAT_ETH*rre))
    * (la.d ? la.d.reduce((a,v,i)=>a+v*RD[i],0)/ENG_Q.reduce((a,v,i)=>a+v*RD[i],0) : 1)
    * Math.pow(dR,eps);
  if(basisMode==='ga' && la.ga) return la.ga[cat]/GA_GB[cat];
  if(basisMode==='blend' && la.ga){
    const w = la.a/(la.a+BLEND_K);
    return Math.exp(w*Math.log(la.ga[cat]/GA_GB[cat])+(1-w)*Math.log(mA));
  }
  return mA;
}

function laAdj8All(eps, basisMode){
  return LAS.map(la => calcAdjForLA(la, 2, eps, basisMode));
}

// Per-authority PGSI 1+ (%) under current basis/sliders, with 25% ceiling and demographic feasibility cap
function laPrev1All(vals, basisMode){
  const sl = [vals.p12, vals.p37, vals.p8];
  return LAS.map(la => {
    const parts = [0,1,2].map(cat => sl[cat] * calcAdjForLA(la, cat, vals.sup, basisMode));
    const tot = parts[0]+parts[1]+parts[2];
    const feas = 1.5 * (dot(la.ab,R12)+dot(la.ab,R37)+dot(la.ab,R8)) / 100;
    return Math.min(tot, feas, vals.ceil);
  });
}

function basisAgreement(eps){
  const a = laAdj8All(eps,'model'), b = laAdj8All(eps,'ga');
  const n=a.length, ma=a.reduce((x,y)=>x+y)/n, mb=b.reduce((x,y)=>x+y)/n;
  let sab=0,sa=0,sb=0;
  for(let i=0;i<n;i++){ sab+=(a[i]-ma)*(b[i]-mb); sa+=(a[i]-ma)**2; sb+=(b[i]-mb)**2; }
  return sab/Math.sqrt(sa*sb);
}

// Main calc — takes the full slider/state object, returns all derived results
function calc(s){
  const { pop, p12, p37, p8, ao, qalyK, young, male, eth: ethsh, sup: eps, ceil, af,
          dw12, dw37, dw8, dwao12, dwao37, dwao8, selLA, basisMode, vis } = s;

  let bands;
  if(selLA){ bands = selLA.ab.slice(); }
  else {
    const yScale = young/NAT_YOUNG, oScale = (100-young)/(100-NAT_YOUNG);
    bands = NAT_AB.map((b,i)=> i<2 ? b*yScale : b*oScale);
  }
  const ageAdj = R => dot(bands,R)/dot(NAT_AB,R);
  const sexAdj = (rm,rf) => (male*rm+(100-male)*rf)/(NAT_MALE*rm+(100-NAT_MALE)*rf);
  const ethAdj = rr => ((100-ethsh)+ethsh*rr)/((100-NAT_ETH)+NAT_ETH*rr);
  const dens = selLA ? (selLA.g.reduce((a,b)=>a+b,0)/(expPop(selLA)+(vis||0))*1e5) : GB_DENS;
  const dRatio = Math.min(Math.max(dens/GB_DENS, SUPPLY_CAP[0]), SUPPLY_CAP[1]);
  const supAdj = Math.pow(dRatio, eps);
  const depAdj = R => (selLA && selLA.d) ? selLA.d.reduce((a,v,i)=>a+v*R[i],0)/ENG_Q.reduce((a,v,i)=>a+v*R[i],0) : 1;

  let adj8  = ageAdj(R8) * sexAdj(RM8,RF8) * ethAdj(RRE8) * depAdj(RD8) * supAdj;
  let adj37 = ageAdj(R37)* sexAdj(RM37,RF37)* ethAdj(RRE17)* depAdj(RD37)* supAdj;
  let adj12 = ageAdj(R12)* sexAdj(RM12,RF12)* ethAdj(RRE17)* depAdj(RD12)* supAdj;

  if(basisMode==='ga' && selLA && selLA.ga){
    adj12 = selLA.ga[0]/GA_GB[0]; adj37 = selLA.ga[1]/GA_GB[1]; adj8 = selLA.ga[2]/GA_GB[2];
  } else if(basisMode==='blend' && selLA && selLA.ga){
    const w = selLA.a/(selLA.a+BLEND_K);
    const bl=(gaR,mA)=> Math.exp(w*Math.log(gaR)+(1-w)*Math.log(mA));
    adj12 = bl(selLA.ga[0]/GA_GB[0], adj12);
    adj37 = bl(selLA.ga[1]/GA_GB[1], adj37);
    adj8  = bl(selLA.ga[2]/GA_GB[2], adj8);
  }

  const profYoung = (bands[0]*R8[0]+bands[1]*R8[1]) / dot(bands,R8) * 100;
  const profMale  = (male*RM8) / (male*RM8 + (100-male)*RF8) * 100;
  const profEth   = (ethsh*RRE8) / (ethsh*RRE8 + (100-ethsh)) * 100;

  let p12e = p12*adj12, p37e = p37*adj37, p8e = p8*adj8;
  const sum1p = p12e+p37e+p8e;
  let ceilHit=false;
  if(sum1p > ceil){ const f=ceil/sum1p; p12e*=f; p37e*=f; p8e*=f; ceilHit=true; }
  const adjAO = (p12e+p37e+p8e)/(p12+p37+p8);
  const aoe = ao*adjAO;

  const n12 = pop*p12e/100, n37 = pop*p37e/100, n8 = pop*p8e/100;
  const n1plus = n12+n37+n8;
  const nAo = pop*aoe/100;
  const w12 = n12*AO_RATIO_12, w37 = n37*AO_RATIO_37, w8 = n8*AO_RATIO_8, wSum = w12+w37+w8;
  const nAo12 = wSum>0 ? nAo*w12/wSum : 0, nAo37 = wSum>0 ? nAo*w37/wSum : 0, nAo8 = wSum>0 ? nAo*w8/wSum : 0;
  const yldAo8 = nAo8*dwao8*af, yldAo37 = nAo37*dwao37*af, yldAo12 = nAo12*dwao12*af;
  const yldAo = yldAo8+yldAo37+yldAo12;
  const yld12 = n12*dw12*af, yld37 = n37*dw37*af, yld8 = n8*dw8*af;
  const yld = yld12+yld37+yld8+yldAo;
  const money = yld*qalyK*1000;

  const ohidLo = pop*OHID_LO_PER_ADULT, ohidHi = pop*OHID_HI_PER_ADULT;
  const vicAdj = SEV_HIGH*(p8e/HSE_P8) + SEV_ATRISK*((p12e+p37e)/HSE_P17);
  const vicLo = pop*VIC_BASE_LO*vicAdj, vicMid = pop*VIC_BASE_MID*vicAdj, vicHi = pop*VIC_BASE_HI*vicAdj;

  const yldCiLo = (n12*(7.9/8.8)*dw12 + n37*(2.8/3.1)*dw37 + n8*(2.2/2.7)*dw8)*af + yldAo*(8/9)*( (7.9/8.8+2.8/3.1+2.2/2.7)/3 );
  const yldCiHi = (n12*(9.8/8.8)*dw12 + n37*(3.6/3.1)*dw37 + n8*(3.2/2.7)*dw8)*af + yldAo*(10/9)*( (9.8/8.8+3.6/3.1+3.2/2.7)/3 );

  let rank = 1;
  if(selLA){
    const myAdj = adj8;
    laAdj8All(eps, basisMode).forEach(a=>{ if(a > myAdj+1e-9) rank++; });
  }

  const aoShare8 = yldAo>0 ? Math.round(yldAo8/yldAo*100) : 0;
  const aoB01=bands[0]+bands[1], aoB23=bands[2]+bands[3], aoB55=bands[4]+bands[5]+bands[6];
  const aoWsum=aoB01*RAO_AGE[0]+aoB23*RAO_AGE[1]+aoB55*RAO_AGE[2];
  const aoYoungShare = Math.round(aoB01*RAO_AGE[0]/aoWsum*100);
  const aoFemShare = Math.round(((100-male)*RAO_F)/(((100-male)*RAO_F)+male*RAO_M)*100);

  const shLow = yld>0 ? yld12/yld : 0, shMod = yld>0 ? yld37/yld : 0, shHigh = yld>0 ? yld8/yld : 0, shAo = yld>0 ? yldAo/yld : 0;
  const outsideSevere = Math.round((shLow+shMod+shAo)*100);

  let densText = null, densRank = null;
  if(selLA){
    const densAll = LAS.map(l=> l.g.reduce((a,b)=>a+b,0)/expPop(l)*1e5);
    let dRank=1; densAll.forEach(d=>{ if(d>dens+1e-9) dRank++; });
    densRank = dRank;
    densText = dens.toFixed(1);
  }

  return {
    pop,p12,p37,p8,p12e,p37e,p8e,aoe,adjAO,ceil,ceilHit,adj8,adj37,adj12,ao,af,qalyK,
    dw12,dw37,dw8,dwao12,dwao37,dwao8,
    n12,n37,n8,n1plus,nAo,nAo8,nAo37,nAo12,
    yld,yldAo,yldAo8,yldAo37,yldAo12,yld12,yld37,yld8,aoShare8,money,
    ohidLo,ohidHi,vicLo,vicMid,vicHi,outsideSevere,
    yldCiLo,yldCiHi,rank,dens,dRatio,densText,densRank,
    profYoung,profMale,profEth,aoYoungShare,aoFemShare,
    shLow,shMod,shHigh,shAo,bands
  };
}

// ---- Tornado sensitivity ----
function renderTornado(s, res){
  const base = res.yld;
  const gY = (p12e,p37e,p8e,w12,w37,w8)=>{
    const n12=s.pop*p12e/100, n37=s.pop*p37e/100, n8=s.pop*p8e/100;
    const w1=n12*1, w3=n37*3, w8x=n8*6, wS=w1+w3+w8x;
    const nAo=s.pop*s.ao/100;
    const ya = wS>0 ? nAo*(w1/wS)*w12 + nAo*(w3/wS)*w37 + nAo*(w8x/wS)*w8 : 0;
    return (n12*s.dw12 + n37*s.dw37 + n8*s.dw8 + ya)*s.af;
  };
  const cur = [s.dwao12,s.dwao37,s.dwao8];
  const items=[
    {l:'PGSI 8+ prevalence (CI 2.2–3.2%)', lo:gY(res.p12e,res.p37e,2.2*res.adj8,...cur), hi:gY(res.p12e,res.p37e,3.2*res.adj8,...cur)},
    {l:'PGSI 1–2 prevalence (CI 7.9–9.8%)', lo:gY(7.9*res.adj12,res.p37e,res.p8e,...cur), hi:gY(9.8*res.adj12,res.p37e,res.p8e,...cur)},
    {l:'Affected-other weight basis (applied-mean vs direct)', lo:gY(res.p12e,res.p37e,res.p8e,0.05,0.15,0.30), hi:gY(res.p12e,res.p37e,res.p8e,0.17,0.33,0.36)},
    {l:'PGSI 3–7 prevalence (CI 2.8–3.6%)', lo:gY(res.p12e,2.8*res.adj37,res.p8e,...cur), hi:gY(res.p12e,3.6*res.adj37,res.p8e,...cur)},
  ];
  const yGamb = (s.pop*res.p12e/100*s.dw12 + s.pop*res.p37e/100*s.dw37 + s.pop*res.p8e/100*s.dw8)*s.af;
  const yAoCur = base - yGamb;
  items.push({l:'Affected others (8–10% of adults)', lo:yGamb + yAoCur*8/s.ao, hi:yGamb + yAoCur*10/s.ao});
  const f0 = Math.pow(res.dRatio, 0 - s.sup), f3 = Math.pow(res.dRatio, 0.3 - s.sup);
  items.push({l:'Supply elasticity (0–0.3) at local premises density', lo:gY(res.p12e*f0,res.p37e*f0,res.p8e*f0,...cur), hi:gY(res.p12e*f3,res.p37e*f3,res.p8e*f3,...cur)});
  items.push({l:'Causal attribution of elicited weights (0.2–1.0)', lo:base*0.2/(s.af||1), hi:base*1.0/(s.af||1)});
  items.forEach(it=>{ it.swing=Math.abs(it.hi-it.lo); });
  items.sort((a,b)=>b.swing-a.swing);
  const maxDev = Math.max(...items.map(it=>Math.max(Math.abs(it.hi-base),Math.abs(it.lo-base))),1);
  return items.map(it=>({
    ...it,
    left: 50+(Math.min(it.lo,it.hi)-base)/maxDev*48,
    width: Math.max((Math.max(it.lo,it.hi)-Math.min(it.lo,it.hi))/maxDev*48, 0.8)
  }));
}

// ---- Hot zones across GB (top authorities by adjusted PGSI1+/8+) ----
function hotZones(s, basisMode){
  const prevs = laPrev1All(s, basisMode);
  return LAS.map((la,i) => ({
    name: la.n, prev: prevs[i], dens: la.g.reduce((a,b)=>a+b,0)/expPop(la)*1e5
  })).sort((a,b)=>b.prev-a.prev).slice(0,10);
}

// ---- Reusable UI bits ----
const COLORS = {
  ink:'#1B2431', inkSoft:'#4A5568', paper:'#F6F5F1', panel:'#FFFFFF',
  teal:'#0F6B66', tealSoft:'#E3EFEE', claret:'#7D2A3A', claretSoft:'#F5E9EB',
  rose:'#C99AA4', line:'#DDD9CF', amber:'#9C6B1E'
};

function Card({ title, sub, children, style }) {
  return (
    <div className="rounded-lg p-5" style={{ background: COLORS.panel, border: `1px solid ${COLORS.line}`, ...style }}>
      {title && <h2 className="text-sm font-bold uppercase tracking-wide mb-1" style={{ color: COLORS.ink }}>{title}</h2>}
      {sub && <p className="text-xs mb-4" style={{ color: COLORS.inkSoft }}>{sub}</p>}
      {children}
    </div>
  );
}

function Slider({ label, value, onChange, min, max, step, unit, defaultVal, sourceNote }) {
  const pct = ((value - min) / (max - min)) * 100;
  const defPct = defaultVal != null ? ((defaultVal - min) / (max - min)) * 100 : null;
  return (
    <div className="py-3 border-t" style={{ borderColor: COLORS.line, borderTopStyle: 'dashed' }}>
      <div className="flex justify-between items-baseline gap-3 mb-0.5">
        <span className="font-semibold text-sm" style={{ color: COLORS.ink }}>{label}</span>
        <span className="font-mono font-semibold text-base" style={{ color: COLORS.teal, minWidth: 70, textAlign: 'right' }}>
          {typeof value === 'number' ? value.toFixed(step < 1 ? 1 : 0) : value}{unit}
        </span>
      </div>
      {sourceNote && <div className="text-xs mb-3" style={{ color: COLORS.inkSoft }}>{sourceNote}</div>}
      <div className="relative py-1 pb-2">
        <input
          type="range" min={min} max={max} step={step} value={value}
          onChange={e => onChange(parseFloat(e.target.value))}
          className="w-full cursor-pointer"
          style={{ accentColor: COLORS.teal }}
        />
        {defPct != null && (
          <div className="absolute -top-1 text-[10px] font-mono" style={{ left: `${defPct}%`, transform: 'translateX(-50%)', color: COLORS.claret }}>▾</div>
        )}
      </div>
    </div>
  );
}

function NumberBox({ label, cat, value, onChange }) {
  return (
    <div className="rounded-md p-3" style={{ border: `1px solid ${COLORS.line}` }}>
      <label className="block text-xs font-semibold mb-0.5" style={{ color: COLORS.ink }}>{label}</label>
      <span className="block font-mono text-xs mb-2" style={{ color: COLORS.inkSoft }}>{cat}</span>
      <input
        type="number" min="0" max="1" step="0.01" value={value}
        onChange={e => onChange(parseFloat(e.target.value) || 0)}
        className="w-full font-mono text-lg font-semibold px-2 py-1.5 rounded"
        style={{ border: `1.5px solid ${COLORS.ink}`, background: COLORS.paper, color: COLORS.claret }}
      />
    </div>
  );
}

function PillButton({ active, onClick, children }) {
  return (
    <button
      onClick={onClick}
      className="text-xs font-mono px-3 py-1.5 rounded-full mr-2 mb-2"
      style={{
        border: `1px solid ${active ? COLORS.teal : COLORS.line}`,
        background: active ? COLORS.teal : COLORS.panel,
        color: active ? '#fff' : COLORS.inkSoft,
        fontWeight: active ? 600 : 500
      }}
    >
      {children}
    </button>
  );
}

// ---- GB choropleth map ----
function GBMap({ vals, basisMode, selLA, onSelect }) {
  const prevs = useMemo(() => laPrev1All(vals, basisMode), [vals, basisMode]);
  const lo = Math.min(...prevs), hi = Math.max(...prevs);
  const mix = (t) => {
    const a = [241,230,232], b = [125,42,58]; // rose -> claret
    const u = Math.pow(Math.max(0, Math.min(1, t)), 0.75);
    return `rgb(${a.map((av,i) => Math.round(av + (b[i]-av)*u)).join(',')})`;
  };
  return (
    <div>
      <svg viewBox="0 0 520 1049" style={{ width: '100%', maxWidth: 300, height: 'auto', display: 'block', margin: '0 auto' }} role="img" aria-label="Map of Great Britain shaded by estimated PGSI 1+ prevalence per authority">
        {LAS.map((la, i) => {
          const d = MAP[la.c];
          if (!d) return null;
          const t = (prevs[i] - lo) / ((hi - lo) || 1);
          const sel = selLA && selLA.c === la.c;
          return (
            <path
              key={la.c} d={d}
              fill={mix(t)}
              stroke={sel ? COLORS.ink : '#FFFFFF'}
              strokeWidth={sel ? 1.8 : 0.7}
              style={{ cursor: 'pointer' }}
              tabIndex={0} role="button" aria-label={la.n}
              onClick={() => onSelect(la)}
              onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onSelect(la); } }}
            >
              <title>{la.n}: {prevs[i].toFixed(1)}% est. PGSI 1+</title>
            </path>
          );
        })}
      </svg>
      <div className="flex justify-between text-[10px] font-mono mt-2" style={{ color: COLORS.inkSoft }}>
        <span>{lo.toFixed(1)}%</span>
        <span>{hi.toFixed(1)}%</span>
      </div>
      <p className="text-xs mt-1" style={{ color: COLORS.inkSoft }}>Adjusted PGSI 1+ prevalence by authority. Click a shape to select it.</p>
    </div>
  );
}

export default function GhukBurdenCalculator() {
  const [mode, setMode] = useState('basic'); // 'basic' | 'advanced'
  const [popInput, setPopInput] = useState('53,529,600');
  const [laQuery, setLaQuery] = useState('');
  const [selLA, setSelLA] = useState(null);
  const [basisMode, setBasisMode] = useState('blend');
  const [activeScen, setActiveScen] = useState('mid');
  const [vis, setVis] = useState('');

  const [vals, setVals] = useState({ ...DEFAULTS });

  const pop = useMemo(() => {
    const raw = popInput.replace(/[^0-9]/g, '');
    return raw ? Math.min(parseInt(raw, 10), 70000000) : 0;
  }, [popInput]);

  function setVal(key, v) {
    setVals(prev => ({ ...prev, [key]: v }));
    setActiveScen('custom');
  }

  function applyScenario(key) {
    setActiveScen(key);
    const scen = SCENARIOS[key];
    setVals({ ...DEFAULTS, af: 1, ...scen.vals });
  }

  function resetAll() {
    setSelLA(null); setLaQuery(''); setVis('');
    setPopInput('53,529,600');
    setVals({ ...DEFAULTS });
    setActiveScen('mid');
    setBasisMode('blend');
  }

  function selectLA(la) {
    setSelLA(la);
    setLaQuery(la.n);
    setPopInput(fmtPop(la.a));
    setVal('young', +(la.ab[0] + la.ab[1]).toFixed(1));
    setVal('male', la.m);
    if (la.e && la.e.W != null) setVal('eth', +(100 - la.e.W).toFixed(1));
    setVis('');
  }

  const state = {
    pop, ...vals, eth: vals.eth, sup: vals.sup, ceil: vals.ceil,
    selLA, basisMode, vis: parseFloat((vis||'').replace(/[^0-9.]/g,'')) || 0
  };

  const res = useMemo(() => calc(state), [
    pop, vals, selLA, basisMode, vis
  ]);

  const tornado = useMemo(() => renderTornado(vals, res), [vals, res, state.sup]);
  const hotList = useMemo(() => hotZones(vals, basisMode), [vals, basisMode]);

  const matchedLA = useMemo(() => {
    if (!laQuery) return null;
    return LAS.find(l => l.n.toLowerCase() === laQuery.trim().toLowerCase());
  }, [laQuery]);

  function handleLaInput(v) {
    setLaQuery(v);
    const la = LAS.find(l => l.n.toLowerCase() === v.trim().toLowerCase());
    if (la) selectLA(la);
    else if (!v) { setSelLA(null); }
  }

  const [copied, setCopied] = useState(false);
  function copySummary() {
    const d = res;
    const txt = `Gambling harm burden estimate — ${selLA ? selLA.n+', ' : ''}adult population ${fmtPop(d.pop)}
(Generated with the Gambling Harm UK burden calculator; demographics from ONS mid-2023 estimates${selLA ? ' for '+selLA.n : ''})

• An estimated ${round3sf(d.n1plus).toLocaleString('en-GB')} adults are experiencing gambling harm (PGSI 1+, demographically adjusted from GSGB 2024 rates: ×${d.adj8.toFixed(2)} for PGSI 8+ given local age-sex structure), of whom ${round3sf(d.n8).toLocaleString('en-GB')} score PGSI 8+ (effective ${d.p8e.toFixed(1)}%).
${selLA ? '• Licensed gambling premises (Gambling Commission register): '+selLA.g[0]+' betting shops, '+selLA.g[1]+' adult gaming centres, '+selLA.g[2]+' bingo premises, '+selLA.g[3]+' casinos — '+(selLA.g.reduce((a,b)=>a+b,0)/expPop(selLA)*1e5).toFixed(1)+' premises per 100k exposure population vs 11.7 GB average.\\n' : ''}• A further ${round3sf(d.nAo).toLocaleString('en-GB')} adults are affected by someone else's gambling (${d.aoe.toFixed(1)}% locally adjusted from the GSGB 2024 9% national rate); children affected are additional and not counted. An estimated ${round3sf(d.nAo8).toLocaleString('en-GB')} are affected by someone at PGSI 8+ — ${d.aoShare8}% of the affected-other health burden traces to the severe end.
• Applying health disutility weights (PGSI 1–2 = ${d.dw12}; 3–7 = ${d.dw37}; 8+ = ${d.dw8}; affected others by source severity = ${d.dwao12}/${d.dwao37}/${d.dwao8}), gambling harm removes an estimated ${round3sf(d.yld).toLocaleString('en-GB')} years of health and wellbeing from this population every year (elicited-weight basis; not comparable to GBD YLD) — ${d.outsideSevere}% of it outside the most severe category.
• Sensitivity: valued at £${(d.qalyK*1000).toLocaleString('en-GB')} per healthy year (HM Treasury Green Book wellbeing value), the loss equates to ≈ ${fmtMoney(d.money)} per year — an upper-envelope welfare framing, not a cashflow cost.
• OHID's (2023) narrow cost-of-illness method scales to ${fmtMoney(d.ohidLo)}–${fmtMoney(d.ohidHi)}/yr for this population. Full social-cost accounting (Browne, Tulloch et al., 2025) gives ≈ ${fmtMoney(d.vicMid)}/yr (${fmtMoney(d.vicLo)}–${fmtMoney(d.vicHi)}). Figures are non-additive and indicative of scale.

PGSI 1+ ceiling: ${d.ceil}%${d.ceilHit?' (binding — categories rescaled)':''}. Local variation basis: ${basisMode==='ga'?'GambleAware–YouGov MRP (survey geography, GSGB-anchored)':basisMode==='blend'?'Blended: population-weighted combination of MRP survey and structural standardisation, GSGB-anchored':'GHUK standardisation (age, sex, ethnicity, deprivation, supply)'}. Scenario: ${activeScen==='mid'?'Central (published defaults)':activeScen==='lo'?'Conservative':activeScen==='hi'?'Upper bound':activeScen==='bgps'?'Legacy (BGPS 2010)':activeScen==='moa'?'Adjusted weights':'Custom'}. Causal-attribution factor applied: ${d.af.toFixed(2)}.

Source: Gambling Harm UK Burden Calculator v2.6 (defaults frozen as v2.5, 11 July 2026).`;
    navigator.clipboard?.writeText(txt).then(() => {
      setCopied(true); setTimeout(() => setCopied(false), 1800);
    }).catch(() => {});
  }

  const basisNotes = {
    blend: 'Blended (recommended): GambleAware–YouGov MRP survey geography and structural standardisation (age × sex × ethnicity × deprivation × supply) combined in proportion to population — survey evidence dominates in large authorities, structural evidence stabilises small ones. National levels anchored to GSGB.',
    ga: `Survey basis: OCSI MRP estimates (GambleAware–YouGov Treatment & Support Surveys, 2024 profiles) applied as each authority's ratio to the GB baseline, anchored to GSGB levels. Agreement with the structural basis across 207 authorities: r = ${basisAgreement(vals.sup).toFixed(2)}.`,
    model: 'Structural basis: indirect standardisation (age × sex × ethnicity × deprivation × supply) applied to GSGB national rates. Deprivation uses exact GSGB rates by English IMD quintile; Scottish and Welsh authorities carry no deprivation term.'
  };

  const scenLabel = activeScen==='mid'?'Central (published defaults)':activeScen==='lo'?'Conservative':activeScen==='hi'?'Upper bound':activeScen==='bgps'?'Legacy mode anchor (BGPS 2010)':activeScen==='moa'?'Adjusted weights (Moayeri 2020 / GHS-AO)':'Custom';

  return (
    <div className="min-h-screen" style={{ background: COLORS.paper, color: COLORS.ink, fontFamily: 'system-ui, sans-serif' }}>
      <style>{`
        @media print {
          .ghuk-no-print { display: none !important; }
          .ghuk-print-report { display: block !important; }
        }
        .ghuk-print-report { display: none; }
      `}</style>

      <div className="ghuk-print-report" style={{ padding: 24, color: '#1B2431', fontFamily: 'system-ui, sans-serif' }}>
        <h1 style={{ fontSize: 22, fontWeight: 800, marginBottom: 4 }}>Gambling harm burden estimate — {selLA ? selLA.n : 'Custom population'}</h1>
        <div style={{ fontSize: 12, color: COLORS.inkSoft, marginBottom: 16 }}>
          Adult population {fmtPop(res.pop)} · generated {new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})} · scenario: {scenLabel} · basis: {basisMode==='ga'?'survey (MRP)':basisMode==='blend'?'blended (default)':'structural'}
        </div>
        <div style={{ fontSize: 13, fontWeight: 700, textTransform: 'uppercase', borderBottom: '1px solid #DDD9CF', paddingBottom: 4, marginBottom: 8 }}>Headline burden</div>
        {[
          ['Years of health and wellbeing lost annually (elicited-weight basis), incl. affected others', round3sf(res.yld).toLocaleString('en-GB')],
          ['OHID (2023) cost-of-illness (policy-use reference)', fmtMoney(res.ohidLo)+'–'+fmtMoney(res.ohidHi)+'/yr'],
          ['Full social-cost accounting (Browne, Tulloch et al. 2025 transfer; non-additive)', '≈ '+fmtMoney(res.vicMid)+'/yr'],
          ['Sensitivity: societal wellbeing valuation (£'+(vals.qaly*1000).toLocaleString('en-GB')+'/healthy yr; upper-envelope framing, not a cashflow cost)', '≈ '+fmtMoney(res.money)+'/yr'],
        ].map(([label, val]) => (
          <div key={label} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, padding: '4px 0', borderBottom: '1px solid #EEE' }}>
            <span>{label}</span><b style={{ marginLeft: 12, whiteSpace: 'nowrap' }}>{val}</b>
          </div>
        ))}
        <div style={{ fontSize: 13, fontWeight: 700, textTransform: 'uppercase', borderBottom: '1px solid #DDD9CF', padding: '12px 0 4px' }}>Who is affected</div>
        {[
          ['Adults experiencing gambling harm (PGSI 1+)', '≈ '+round3sf(res.n1plus).toLocaleString('en-GB')],
          ['— of whom PGSI 8+ (severe)', round3sf(res.n8).toLocaleString('en-GB')+' ('+res.p8e.toFixed(1)+'%)'],
          ['— PGSI 3–7', round3sf(res.n37).toLocaleString('en-GB')+' ('+res.p37e.toFixed(1)+'%)'],
          ['— PGSI 1–2', round3sf(res.n12).toLocaleString('en-GB')+' ('+res.p12e.toFixed(1)+'%)'],
          ["Adults affected by someone else's gambling (children additional, uncounted)", '≈ '+round3sf(res.nAo).toLocaleString('en-GB')],
          ['Adults at PGSI 8+ likely not receiving structured treatment (≈95% gap)', '≈ '+round3sf(res.n8*0.95).toLocaleString('en-GB')],
        ].map(([label, val]) => (
          <div key={label} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, padding: '4px 0', borderBottom: '1px solid #EEE' }}>
            <span>{label}</span><b style={{ marginLeft: 12, whiteSpace: 'nowrap' }}>{val}</b>
          </div>
        ))}
        {selLA && (
          <>
            <div style={{ fontSize: 13, fontWeight: 700, textTransform: 'uppercase', borderBottom: '1px solid #DDD9CF', padding: '12px 0 4px' }}>Local area profile — licensed premises (Gambling Commission register, July 2026)</div>
            {PREM_LABELS.map((l, i) => (
              <div key={l} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, padding: '4px 0', borderBottom: '1px solid #EEE' }}>
                <span>{l}</span><b>{selLA.g[i]}</b>
              </div>
            ))}
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, padding: '4px 0', borderBottom: '1px solid #EEE' }}>
              <span>Footfall-adjusted density (GB baseline 11.7 per 100k)</span><b>{res.densText}/100k</b>
            </div>
          </>
        )}
        <div style={{ fontSize: 13, fontWeight: 700, textTransform: 'uppercase', borderBottom: '1px solid #DDD9CF', padding: '12px 0 4px' }}>Method in one paragraph</div>
        <p style={{ fontSize: 11.5, color: COLORS.inkSoft, marginTop: 6, lineHeight: 1.6 }}>
          Burden = population × prevalence × health disutility, counted from PGSI 1+ and including affected others. Prevalence: GSGB 2024 ({vals.p12}/{vals.p37}/{vals.p8}% by category), locally adjusted ×{res.adj8.toFixed(2)} at PGSI 8+ under the {basisMode==='ga'?'survey (MRP)':basisMode==='blend'?'blended':'structural'} basis{res.ceilHit ? '; 25% PGSI 1+ ceiling binding (categories rescaled)' : ''}. Disability weights: Tulloch et al. 2026 / Browne et al. 2016 ({vals.dw12}/{vals.dw37}/{vals.dw8}; affected others {vals.dwao12}/{vals.dwao37}/{vals.dwao8} by source severity). Causal-attribution factor {vals.af.toFixed(2)} applied to all weights. The headline range reflects GSGB sampling CIs only; full uncertainty spans the scenario envelope. "Years of health and wellbeing lost" uses elicited harm-profile weights and is not comparable to GBD YLD. Deprivation is modelled for English authorities (GSGB D.8 × IMD 2019); online gambling has no local supply term; estimates are ecological.
        </p>
      </div>

      <div className="ghuk-no-print">
      <header className="border-b-2 px-4 py-6" style={{ borderColor: COLORS.ink, background: COLORS.panel }}>
        <div className="max-w-6xl mx-auto">
          <div className="text-xs font-mono uppercase tracking-widest mb-2" style={{ color: COLORS.teal }}>Gambling Harm UK · Local Systems Toolkit</div>
          <h1 className="text-2xl md:text-3xl font-extrabold" style={{ letterSpacing: '-0.02em' }}>
            Gambling Harm <span style={{ color: COLORS.claret }}>Burden Calculator</span>
          </h1>
          <p className="text-sm mt-2 max-w-2xl" style={{ color: COLORS.inkSoft }}>
            Estimate the annual health burden of gambling harm for any GB local authority or custom population.
            v2.6 (defaults frozen as v2.5, 11 July 2026).
          </p>
          <div className="mt-4">
            <PillButton active={mode==='basic'} onClick={() => setMode('basic')}>Basic</PillButton>
            <PillButton active={mode==='advanced'} onClick={() => setMode('advanced')}>Advanced — adjust every assumption</PillButton>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 py-8 grid gap-6" style={{ gridTemplateColumns: '1fr', }}>
        <div className="grid gap-6 lg:grid-cols-[1fr_400px]">
          <div className="flex flex-col gap-5">

            {/* Population */}
            <Card title="1 · Your population">
              <input
                type="text" list="la-list" value={laQuery}
                onChange={e => handleLaInput(e.target.value)}
                placeholder="Start typing a local authority…"
                className="w-full px-3 py-2 rounded mb-2 font-mono"
                style={{ border: `2px solid ${COLORS.ink}`, background: COLORS.paper }}
              />
              <datalist id="la-list">
                {LAS.map(la => <option key={la.c} value={la.n} />)}
              </datalist>
              <p className="text-xs mb-3" style={{ color: COLORS.inkSoft }}>
                Selecting an authority unlocks its Census ethnicity profile, licensed-premises counts and local supply data.
              </p>
              <input
                type="text" value={popInput}
                onChange={e => { setPopInput(e.target.value); }}
                onBlur={() => setPopInput(fmtPop(pop))}
                className="w-full px-3 py-2 rounded font-mono text-xl font-semibold"
                style={{ border: `2px solid ${COLORS.ink}`, background: COLORS.paper }}
              />
              <div className="flex flex-wrap gap-2 mt-3">
                {[['GB total', 53529600], ['England', 45300000], ['1 million', 1000000], ['100k', 100000]].map(([label, v]) => (
                  <button key={label} onClick={() => { setSelLA(null); setLaQuery(''); setPopInput(fmtPop(v)); }}
                    className="text-xs font-mono px-3 py-1.5 rounded-full"
                    style={{ border: `1px solid ${COLORS.line}`, color: COLORS.inkSoft }}>{label}</button>
                ))}
              </div>

              {mode === 'advanced' && (
                <>
                  <Slider label="Adults aged 18–34" value={vals.young} onChange={v => setVal('young', v)} min={0} max={60} step={0.5} unit="%" defaultVal={27.6} />
                  <Slider label="Male share" value={vals.male} onChange={v => setVal('male', v)} min={40} max={60} step={0.5} unit="%" defaultVal={48.4} />
                  <Slider label="Minority ethnic share" value={vals.eth} onChange={v => setVal('eth', v)} min={0} max={60} step={0.5} unit="%" defaultVal={18.3} />
                  {selLA && (
                    <div className="mt-2">
                      <label className="text-xs font-semibold block mb-1">Daily visitor-equivalents (optional)</label>
                      <input type="text" value={vis} onChange={e => setVis(e.target.value)}
                        placeholder="e.g. 60,000 — leave blank if not a visitor economy"
                        className="w-full px-3 py-2 rounded text-sm font-mono"
                        style={{ border: `1.5px solid ${COLORS.line}` }} />
                    </div>
                  )}
                  <Slider label="Supply elasticity (ε)" value={vals.sup} onChange={v => setVal('sup', v)} min={0} max={0.5} step={0.05} unit="" defaultVal={0.1} />
                </>
              )}
              <p className="text-xs mt-3" style={{ color: COLORS.inkSoft }}>
                Combined local adjustment: ×{res.adj8.toFixed(2)} (PGSI 8+), ×{res.adj37.toFixed(2)} (3–7), ×{res.adj12.toFixed(2)} (1–2), ×{res.adjAO.toFixed(2)} (affected others)
                {res.ceilHit ? ' — PGSI 1+ ceiling is binding; categories rescaled proportionally.' : ''}
                {!selLA ? ' — select an authority to apply survey-informed local bases.' : ''}
              </p>
              {selLA && (
                <div className="mt-3 text-xs" style={{ color: COLORS.inkSoft }}>
                  Licensed premises (Gambling Commission register): {PREM_LABELS.map((l,i) => `${l} ${selLA.g[i]}`).join(' · ')}.
                  Footfall-adjusted density: {res.densText}/100k (#{res.densRank} of 207, GB baseline 11.7).
                </div>
              )}
            </Card>

            {/* Prevalence */}
            <Card title="2 · Prevalence of gambling harm">
              <div className="mb-3">
                <PillButton active={basisMode==='blend'} onClick={() => setBasisMode('blend')}>Blended ★</PillButton>
                <PillButton active={basisMode==='ga'} onClick={() => setBasisMode('ga')}>Survey (MRP)</PillButton>
                <PillButton active={basisMode==='model'} onClick={() => setBasisMode('model')}>Structural</PillButton>
              </div>
              <p className="text-xs mb-3" style={{ color: COLORS.inkSoft }}>{basisNotes[basisMode]}</p>

              <Slider label="PGSI 1–2 (national)" value={vals.p12} onChange={v => setVal('p12', v)} min={0} max={20} step={0.1} unit="%" defaultVal={8.8} />
              <div className="text-xs -mt-2 mb-2" style={{ color: COLORS.claret }}>local ≈ {res.p12e.toFixed(1)}%</div>

              <Slider label="PGSI 3–7 (national)" value={vals.p37} onChange={v => setVal('p37', v)} min={0} max={10} step={0.1} unit="%" defaultVal={3.1} />
              <div className="text-xs -mt-2 mb-2" style={{ color: COLORS.claret }}>local ≈ {res.p37e.toFixed(1)}%</div>

              <Slider label="PGSI 8+ (national)" value={vals.p8} onChange={v => setVal('p8', v)} min={0} max={6} step={0.1} unit="%" defaultVal={2.7} />
              <div className="text-xs -mt-2 mb-2" style={{ color: COLORS.claret }}>local ≈ {res.p8e.toFixed(1)}%</div>

              <Slider label="Affected others (national)" value={vals.ao} onChange={v => setVal('ao', v)} min={0} max={20} step={0.5} unit="%" defaultVal={9} />
              <div className="text-xs -mt-2 mb-2" style={{ color: COLORS.claret }}>local ≈ {res.aoe.toFixed(1)}%</div>

              {mode === 'advanced' && (
                <Slider label="PGSI 1+ ceiling" value={vals.ceil} onChange={v => setVal('ceil', v)} min={15} max={40} step={1} unit="%" defaultVal={25} />
              )}
            </Card>

            {/* Disutility weights */}
            <Card title="3 · Health disutility" sub="Elicited harm-profile weights (Tulloch et al. 2026; Browne et al. 2016/2017) — not GBD health-state weights.">
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-4">
                <NumberBox label="Gambler" cat="PGSI 1–2" value={vals.dw12} onChange={v => setVal('dw12', v)} />
                <NumberBox label="Gambler" cat="PGSI 3–7" value={vals.dw37} onChange={v => setVal('dw37', v)} />
                <NumberBox label="Gambler" cat="PGSI 8+" value={vals.dw8} onChange={v => setVal('dw8', v)} />
                <NumberBox label="Affected other" cat="src. PGSI 1–2" value={vals.dwao12} onChange={v => setVal('dwao12', v)} />
                <NumberBox label="Affected other" cat="src. PGSI 3–7" value={vals.dwao37} onChange={v => setVal('dwao37', v)} />
                <NumberBox label="Affected other" cat="src. PGSI 8+" value={vals.dwao8} onChange={v => setVal('dwao8', v)} />
              </div>
              {mode === 'advanced' && (
                <Slider label="Causal attribution of elicited weights" value={vals.af} onChange={v => setVal('af', v)} min={0.2} max={1} step={0.05} unit="" defaultVal={1} />
              )}
              <Slider label="Societal value per healthy year lost" value={vals.qaly} onChange={v => setVal('qaly', v)} min={0} max={100} step={5} unit="k" defaultVal={70} />
              <div className="text-right mt-3">
                <button onClick={resetAll} className="text-xs underline" style={{ color: COLORS.inkSoft }}>Reset all to evidence defaults</button>
              </div>
            </Card>

            {/* Scenarios */}
            <Card title="4 · Scenarios & sensitivity">
              <div className="mb-3">
                <PillButton active={activeScen==='bgps'} onClick={() => applyScenario('bgps')}>Legacy (BGPS 2010)</PillButton>
                <PillButton active={activeScen==='moa'} onClick={() => applyScenario('moa')}>Adjusted weights</PillButton>
                <PillButton active={activeScen==='lo'} onClick={() => applyScenario('lo')}>Conservative</PillButton>
                <PillButton active={activeScen==='mid'} onClick={() => applyScenario('mid')}>Central (published)</PillButton>
                <PillButton active={activeScen==='hi'} onClick={() => applyScenario('hi')}>Upper bound</PillButton>
              </div>
              <p className="text-xs mb-4" style={{ color: COLORS.inkSoft }}>
                {activeScen === 'custom' ? 'Custom: one or more values differ from the preset scenarios. The copy summary records every value used.' : SCENARIOS[activeScen]?.note}
              </p>
              <div className="space-y-3">
                {tornado.map((it, i) => (
                  <div key={i}>
                    <div className="flex justify-between text-xs mb-1">
                      <span style={{ color: COLORS.ink }}>{it.l}</span>
                      <span className="font-mono font-semibold">±{round3sf(it.swing/2).toLocaleString('en-GB')}</span>
                    </div>
                    <div className="relative h-2 rounded" style={{ background: COLORS.tealSoft }}>
                      <div className="absolute top-0 h-2 rounded" style={{ left: `${it.left}%`, width: `${it.width}%`, background: COLORS.teal }} />
                      <div className="absolute top-0 h-2 w-px" style={{ left: '50%', background: COLORS.ink }} />
                    </div>
                    <div className="text-[11px] font-mono mt-0.5" style={{ color: COLORS.inkSoft }}>
                      {round3sf(Math.min(it.lo,it.hi)).toLocaleString('en-GB')} – {round3sf(Math.max(it.lo,it.hi)).toLocaleString('en-GB')} wellbeing-years/yr
                    </div>
                  </div>
                ))}
              </div>
            </Card>

            {/* Hot zones + GB map */}
            <Card title="5 · Hot zones across Great Britain" sub="Adjusted PGSI 1+ prevalence by authority under the current basis and sliders. Click the map or a row to select an authority.">
              <div className="grid gap-4 sm:grid-cols-[220px_1fr]">
                <GBMap vals={vals} basisMode={basisMode} selLA={selLA} onSelect={selectLA} />
                <div className="text-xs leading-7" style={{ color: COLORS.inkSoft }}>
                  {hotList.map((pt, i) => (
                    <div key={pt.name}
                      onClick={() => { const la = LAS.find(l => l.n === pt.name); if (la) selectLA(la); }}
                      style={{ cursor: 'pointer' }}>
                      {i+1}. <b style={{ color: COLORS.ink }}>{pt.name}</b> — <span className="font-mono">{pt.prev.toFixed(1)}%</span> est. PGSI 1+ · {pt.dens.toFixed(1)} premises/100k
                    </div>
                  ))}
                </div>
              </div>
              <p className="text-xs mt-3" style={{ color: COLORS.inkSoft }}>
                Note: this port omits the OSM/Overpass local premises supply map from the original tool (live tile/geocoding layers); the GB choropleth, prevalence model and ranking are unchanged.
              </p>
            </Card>
          </div>

          {/* Results panel */}
          <div className="lg:sticky lg:top-4 self-start">
            <Card style={{ border: `2px solid ${COLORS.ink}` }}>
              <div className="text-xs font-mono pb-3 mb-3 border-b" style={{ color: COLORS.inkSoft, borderColor: COLORS.line }}>
                Population: {fmtPop(res.pop)} adults{selLA ? ` — ${selLA.n}` : pop === 53529600 ? ' — Great Britain (all 207 authorities)' : ' — custom population'}
              </div>

              <div className="pb-3 mb-3 border-b" style={{ borderColor: COLORS.ink }}>
                <div className="text-2xl font-extrabold">{fmtPeople(res.yld)}</div>
                <div className="text-xs" style={{ color: COLORS.inkSoft }}>years of health &amp; wellbeing lost annually (elicited-weight basis; not comparable to GBD YLD)</div>
                <div className="text-xs font-mono mt-1" style={{ color: COLORS.inkSoft }}>
                  range {round3sf(res.yldCiLo).toLocaleString('en-GB')} – {round3sf(res.yldCiHi).toLocaleString('en-GB')} (GSGB 95% sampling CIs only)
                </div>
              </div>

              {selLA && (
                <div className="pb-3 mb-3 border-b" style={{ borderColor: COLORS.line }}>
                  <div className="text-xl font-bold" style={{ color: COLORS.teal }}>#{res.rank}</div>
                  <div className="text-xs" style={{ color: COLORS.inkSoft }}>adjusted PGSI 8+ prevalence rank among 207 GB upper-tier authorities (1 = highest)</div>
                </div>
              )}

              <div className="pb-3 mb-3 border-b" style={{ borderColor: COLORS.line }}>
                <strong className="text-xs uppercase tracking-wide">Costs for policy use. </strong>
                <p className="text-xs mt-1" style={{ color: COLORS.inkSoft }}>
                  OHID's (2023) cost-of-illness method scales to <b>{fmtMoney(res.ohidLo)}–{fmtMoney(res.ohidHi)}</b>/yr for this population;
                  full social-cost accounting (Browne, Tulloch et al., 2025) gives <b>≈ {fmtMoney(res.vicMid)}</b>/yr ({fmtMoney(res.vicLo)}–{fmtMoney(res.vicHi)}).
                  Non-additive with each other and with the wellbeing valuation below.
                </p>
                <details className="mt-2">
                  <summary className="text-xs font-semibold cursor-pointer" style={{ color: COLORS.teal }}>Where the wider social costs fall</summary>
                  <div className="mt-2 space-y-1">
                    {VIC_SPLIT.map(([label, share]) => (
                      <div key={label} className="flex justify-between text-xs">
                        <span style={{ color: COLORS.inkSoft }}>{label}</span>
                        <b>{fmtMoney(res.vicMid * share)}</b>
                      </div>
                    ))}
                  </div>
                </details>
              </div>

              <div className="pb-3 mb-3 border-b" style={{ borderColor: COLORS.line }}>
                <div className="text-lg font-bold">≈ {fmtMoney(res.money)}</div>
                <div className="text-xs" style={{ color: COLORS.inkSoft }}>
                  sensitivity: societal wellbeing valuation (× £{(vals.qaly*1000).toLocaleString('en-GB')}/healthy year, Green Book) — an upper-envelope framing, not a cashflow cost; do not sum with the cost lines above
                </div>
              </div>

              <button onClick={copySummary} className="w-full py-2 rounded text-sm font-semibold mb-2" style={{ background: copied ? COLORS.teal : COLORS.ink, color: '#fff' }}>
                {copied ? 'Copied ✓' : 'Copy summary for your report'}
              </button>
              <button onClick={() => window.print()} className="w-full py-2 rounded text-sm font-semibold mb-2" style={{ background: COLORS.teal, color: '#fff' }}>
                Download PDF report for this area
              </button>

              <div className="pt-4 mt-2 border-t" style={{ borderColor: COLORS.line }}>
                <h2 className="text-sm font-bold uppercase tracking-wide mb-3">Who it affects</h2>
                <div className="grid grid-cols-2 gap-3 mb-3">
                  <div>
                    <div className="text-lg font-bold" style={{ color: COLORS.teal }}>{fmtPeople(res.n1plus)}</div>
                    <div className="text-xs" style={{ color: COLORS.inkSoft }}>adults experiencing gambling harm (PGSI 1+)</div>
                  </div>
                  <div>
                    <div className="text-lg font-bold">{fmtPeople(res.nAo)}</div>
                    <div className="text-xs" style={{ color: COLORS.inkSoft }}>adults affected by someone else's gambling</div>
                  </div>
                </div>
                <div className="text-xs space-y-1 mb-3" style={{ color: COLORS.inkSoft }}>
                  <div className="flex justify-between"><span>Aged 18–34</span><b>{Math.round(res.profYoung)}% (vs {Math.round(res.bands[0]+res.bands[1])}% of adults)</b></div>
                  <div className="flex justify-between"><span>Men</span><b>{Math.round(res.profMale)}% (vs {Math.round(vals.male)}% of adults)</b></div>
                  <div className="flex justify-between"><span>Minority ethnic</span><b>{Math.round(res.profEth)}% (vs {Math.round(vals.eth)}% of adults)</b></div>
                </div>
                <div className="text-xs mb-3" style={{ color: COLORS.inkSoft }}>
                  {res.aoShare8}% of affected-other health burden traces to people at PGSI 8+ — harm to families concentrates at the severe end, the mirror of the gambler-side pattern.
                </div>
                <div className="w-full h-3 rounded overflow-hidden flex mb-2">
                  <div style={{ width: `${res.shLow*100}%`, background: COLORS.claretSoft }} />
                  <div style={{ width: `${res.shMod*100}%`, background: COLORS.rose }} />
                  <div style={{ width: `${res.shHigh*100}%`, background: COLORS.claret }} />
                  <div style={{ width: `${res.shAo*100}%`, background: COLORS.teal }} />
                </div>
                <div className="flex flex-wrap gap-3 text-[11px]" style={{ color: COLORS.inkSoft }}>
                  <span>PGSI 1–2 {Math.round(res.shLow*100)}%</span>
                  <span>PGSI 3–7 {Math.round(res.shMod*100)}%</span>
                  <span>PGSI 8+ {Math.round(res.shHigh*100)}%</span>
                  <span>Affected others {Math.round(res.shAo*100)}%</span>
                </div>
                <p className="text-xs mt-2" style={{ color: COLORS.inkSoft }}>
                  {res.outsideSevere > 50 ? `${res.outsideSevere}% of the health burden sits outside the most severe category — counting only PGSI 8+ misses most of the harm.` : 'Most of the health burden under these assumptions sits in the most severe category.'}
                </p>
              </div>
            </Card>
          </div>
        </div>
      </main>

      <footer className="px-4 py-6 text-xs" style={{ color: COLORS.inkSoft, borderTop: `1px solid ${COLORS.line}` }}>
        <div className="max-w-6xl mx-auto">
          v2.6 (presentation revision, 12 July 2026; parameters frozen as v2.5, 11 July 2026) · Gambling Harm UK ·
          React port — local premises supply map (OSM/Overpass) omitted; GB choropleth, PDF report and copy summary included. Estimates are indicative.
        </div>
      </footer>
      </div>
    </div>
  );
}
